mutations.replace:
const name = process.env.COTAL_NAME?.trim();
const id = process.env.COTAL_ID?.trim();
const owner = process.env.COTAL_OWNER?.trim();
const actor = process.env.COTAL_ACTOR?.trim();
if (!name || (!id && !(owner && actor))) process.exit(1);
const opened = await openTransient(values, name);

card: {
  name,
  kind: "endpoint",
  ...(process.env.COTAL_OWNER && process.env.COTAL_ACTOR
    ? { owner: process.env.COTAL_OWNER, actor: process.env.COTAL_ACTOR }
    : process.env.COTAL_ID
      ? { owner: "local", actor: process.env.COTAL_ID }
      : {}),
},
